export interface TocItem {
  id: string;
  text: string;
  level: number;
}

const ALERT_LABELS: Record<string, string> = {
  note: 'NOTE · 说明',
  tip: 'TIP · 提示',
  important: 'IMPORTANT · 重要',
  warning: 'WARNING · 避坑提示',
  caution: 'CAUTION · 风险警示',
};

/**
 * Post-processes HTML generated by Astro's built-in GFM + Shiki pipeline:
 * 1. Strips accidental duplicate leading <h1> if author kept `# Title` in Markdown body
 * 2. Injects hover anchor links on <h2> and <h3> headings
 * 3. Wraps <table> in responsive horizontal scroll container (.article-table-wrap)
 * 4. Transforms GitHub-style Alerts (> [!WARNING]) into structured semantic callouts
 * 5. Adds safe target="_blank" to external http(s) links and lazy-loading to images
 */
export function enhanceArticleHtml(rawHtml: string): string {
  let html = rawHtml.trimStart().replace(/^<h1\b[^>]*>[\s\S]*?<\/h1>\s*/i, '');

  const anchorSvg = `<svg class="h-4 w-4 opacity-0 group-hover:opacity-100 transition-opacity text-[var(--accent)]" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>`;

  html = html.replace(
    /<h([23])\s+id="([^"]+)"([^>]*)>([\s\S]*?)<\/h\1>/g,
    (_m, depth: string, id: string, attrs: string, inner: string) =>
      `<h${depth} id="${id}" class="group scroll-mt-24 flex items-center gap-2"${attrs}><span class="group-hover:text-[var(--accent)] transition-colors">${inner}</span><a href="#${id}" class="heading-anchor hidden sm:inline-flex items-center text-[var(--text-tertiary)] hover:text-[var(--accent)] no-underline" aria-label="锚点跳转">${anchorSvg}</a></h${depth}>`
  );

  html = html
    .replace(/<table>/g, '<div class="article-table-wrap"><table>')
    .replace(/<\/table>/g, '</table></div>');

  html = html.replace(
    /<blockquote>\s*<p>\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\](?:\s*<br\s*\/?>|\s*\n)?([\s\S]*?)<\/blockquote>/gi,
    (_match, rawType: string, rest: string) => {
      const type = rawType.toLowerCase();
      const label = ALERT_LABELS[type] || rawType.toUpperCase();
      const trimmed = rest.trim();
      const body = trimmed.startsWith('</p>') ? trimmed.slice(4).trim() : `<p>${trimmed}`;
      return `<div class="article-alert article-alert-${type}" role="note"><div class="article-alert-title">${label}</div>${body}</div>`;
    }
  );

  html = html
    .replace(/<a href="(https?:\/\/[^"]+)"(?![^>]*target=)/g, '<a href="$1" target="_blank" rel="noopener noreferrer"')
    .replace(/<img(?![^>]*loading=)\s/g, '<img loading="lazy" decoding="async" ');

  return html;
}
